  function positionHUD() {
    var d = ensureData();
    var box = document.getElementById("gVitalsHud");
    var main = document.getElementById("main");
    var inputbar = document.getElementById("inputbar");
    var controls = document.getElementById("controls");
    var mainRect;
    var inputRect;
    var controlsRect;
    var height;
    var topBelow;
    var topAbove;
    var bottomLimit;
    var chosenTop;
    var width;

    if (!box) {
      return;
    }

    height = parseInt(d.height, 10) || 42;

    if (main) {
      mainRect = main.getBoundingClientRect();
      width = mainRect.width + d.widthAdjust;

      if (width < 200) {
        width = 200;
      }

      box.style.left = (mainRect.left + d.leftOffset) + "px";
      box.style.width = width + "px";
    } else {
      box.style.left = d.leftOffset + "px";
      box.style.width = "calc(100% + " + d.widthAdjust + "px)";
    }

    if (!inputbar) {
      box.style.top = "";
      box.style.bottom = "34px";
      return;
    }

    inputRect = inputbar.getBoundingClientRect();

    if (controls) {
      controlsRect = controls.getBoundingClientRect();
      bottomLimit = controlsRect.top - 2;
    } else {
      bottomLimit = window.innerHeight - 4;
    }

    topBelow = inputRect.bottom + 2;
    topAbove = inputRect.top - height - 2;

    if (d.position === "above") {
      chosenTop = topAbove;
    } else if (d.position === "below") {
      chosenTop = topBelow;
    } else {
      if (topBelow + height <= bottomLimit) {
        chosenTop = topBelow;
      } else {
        chosenTop = topAbove;
      }
    }

    chosenTop += d.yOffset;

    if (chosenTop < 0) {
      chosenTop = 0;
    }

    box.style.top = chosenTop + "px";
    box.style.bottom = "";
  }

