      addCommand(commandText);
      return;
    }

    if (action === "remove" || action === "delete") {
      removeCommand(a2);
      return;
    }

    if (action === "status") {
      status();
      return;
    }

    if (action === "reset") {
      resetDefaults();
      return;
    }

    if (action === "backup") {
      saveBackup();
      append("GWLoot browser backup saved.", goodColor);
      return;
    }

    if (action === "restore") {
      restoreBackup();
      return;
    }

