    var j;

    /*
      Do not auto-popout Quest/AutoHunter during tab reset.
      Just remove our tab containers. The user can run `gwl tabs float`
      if they explicitly want floating windows.
    */

    for (i = 0; i < ids.length; i++) {
      el = getEl(ids[i]);

      if (el) {
