      if (handles[i] && handles[i].parentElement) {
        handles[i].parentElement.removeChild(handles[i]);
      }
    }

    for (i = oldHandles.length - 1; i >= 0; i--) {
      if (oldHandles[i] && oldHandles[i].parentElement) {
