    for (key in drag.positions) {
      if (!drag.positions.hasOwnProperty(key)) {
        continue;
      }

      /*
        Do not ever reapply saved positions to these built-in core controls.
        Older versions could save bad values and cause clipping/click issues.
      */
      if (
        key === "controls" ||
        key === "status" ||
        key === "main" ||
        key === "inputbar" ||
        key === "mudoutput" ||
        key === "genesisQuestTracker" ||
        key === "gwhuntHud"
      ) {
        continue;
      }

      el = byId(key);
      p = drag.positions[key];

      if (!el || !p) {
        continue;
      }

      el.style.position = p.position || "fixed";

      if (p.left) {
        el.style.left = p.left;
      }

      if (p.top) {
        el.style.top = p.top;
      }

      if (p.width) {
        el.style.width = p.width;
      }

      if (p.height) {
        el.style.height = p.height;
      }
    }
