    if (mode === "outside") {
      top = Math.max(0, rect.top - 20);
    } else if (mode === "bottom") {
      top = Math.max(0, rect.bottom - 20);
    } else {
      top = Math.max(0, rect.top + 4);
    }

    handle.style.left = left + "px";
    handle.style.top = top + "px";
    handle.style.maxWidth = Math.max(120, Math.min(260, rect.width - 10)) + "px";
    handle.textContent = "↕ " + label;
