    /*
      Make the target movable only after capturing its current position.
      Keep pointer events normal, so copy/paste/clicking still works.
    */
    el.style.position = "fixed";
    el.style.left = rect.left + "px";
    el.style.top = rect.top + "px";

    if (!el.style.width) {
      el.style.width = rect.width + "px";
    }

    if (!el.style.height) {
      el.style.height = rect.height + "px";
    }

    el.style.resize = "both";
    el.style.overflow = "auto";
    el.style.boxSizing = "border-box";
    el.style.pointerEvents = "auto";

    handle = document.createElement("div");
    handle.className = "gwl-drag-handle";
    handle.style.position = "fixed";
    handle.style.height = "18px";
    handle.style.lineHeight = "18px";
    handle.style.minWidth = "130px";
    handle.style.padding = "0 8px";
    handle.style.background = "rgba(6,12,16,0.96)";
    handle.style.color = "#80d0ff";
    handle.style.border = "1px solid #3d7080";
    handle.style.borderRadius = "4px";
    handle.style.fontFamily = "monospace";
    handle.style.fontSize = "10px";
    handle.style.cursor = "move";
    handle.style.userSelect = "none";
    handle.style.pointerEvents = "auto";
    handle.style.zIndex = "1000002";
    handle.style.boxSizing = "border-box";

    document.body.appendChild(handle);
    placeHandle(handle, el, label);

    handle.addEventListener("mousedown", function (event) {
      var startX = event.clientX;
      var startY = event.clientY;
      var elRect = el.getBoundingClientRect();
      var hRect = handle.getBoundingClientRect();
      var startLeft = elRect.left;
      var startTop = elRect.top;
      var handleStartLeft = hRect.left;
      var handleStartTop = hRect.top;

      function onMove(moveEvent) {
        var dx = moveEvent.clientX - startX;
        var dy = moveEvent.clientY - startY;

        el.style.left = String(startLeft + dx) + "px";
        el.style.top = String(startTop + dy) + "px";
        handle.style.left = String(handleStartLeft + dx) + "px";
        handle.style.top = String(handleStartTop + dy) + "px";
      }

      function onUp() {
        document.removeEventListener("mousemove", onMove, true);
        document.removeEventListener("mouseup", onUp, true);
        storeDragPosition(el);
      }

      event.preventDefault();
      event.stopPropagation();

      document.addEventListener("mousemove", onMove, true);
      document.addEventListener("mouseup", onUp, true);
    }, true);

    if (typeof ResizeObserver !== "undefined") {
      el._gwlResizeObserver = new ResizeObserver(function () {
        if (getDragData().enabled) {
          storeDragPosition(el);
          placeHandle(handle, el, label);
        }
      });

      el._gwlResizeObserver.observe(el);
    }

    el._gwlDragReady = true;
  }

  function setDragHandlePosition(value) {
