  function nudgeInputBar(direction, amount) {
    var d = ensureData();
    var currentBottom = parseInt(d.input.bottom, 10);
    var currentLeft = parseInt(d.input.left, 10);

    if (isNaN(currentBottom)) {
      currentBottom = 0;
    }

    if (isNaN(currentLeft)) {
      currentLeft = 0;
    }

    /*
      Input uses transform offsets:
      - bottom offset raises/lowers it
      - left offset moves it left/right
    */
    if (direction === "up") {
      currentBottom += amount;
    } else if (direction === "down") {
      currentBottom -= amount;
    } else if (direction === "left") {
      currentLeft -= amount;
    } else if (direction === "right") {
      currentLeft += amount;
    } else {
      append("Usage: gwl move input up/down/left/right [pixels]", warnColor);
      return;
    }

    if (currentBottom < 0) {
      currentBottom = 0;
    }

    if (currentBottom > 200) {
      currentBottom = 200;
    }

    if (currentLeft < -1000) {
      currentLeft = -1000;
    }

    if (currentLeft > 1000) {
      currentLeft = 1000;
    }

    d.input.bottom = String(currentBottom);
    d.input.left = String(currentLeft);

    save();
    applyLayout();

    append("Input offset: up " + currentBottom + "px, left " + currentLeft + "px.", goodColor);
  }


  function nudgeOutputHeight(direction, amount) {
    var d = ensureData();
    var wrapper = getEl("div.output-wrapper");
    var current;

    if (d.output.height) {
      current = parseInt(d.output.height, 10);
    } else if (wrapper) {
      current = Math.round(wrapper.getBoundingClientRect().height);
    } else {
      current = 700;
    }

    if (isNaN(current) || current < 200) {
      current = 700;
    }

    if (direction === "up") {
      current -= amount;
    } else if (direction === "down") {
      current += amount;
    } else {
      append("Output only supports up/down height nudging. Use: gwl move output up 20 or gwl move output down 20", warnColor);
      return;
    }

    if (current < 200) {
      current = 200;
    }

    if (current > 2000) {
      current = 2000;
    }

    d.output.height = String(current);
    save();
    applyLayout();

    append("Output height set to " + current + "px.", goodColor);
  }

  function nudgeNamedTarget(targetName, direction, amountText) {
    var amount = parseInt(amountText, 10);
    var dx = 0;
    var dy = 0;
    var el = null;

    targetName = lower(targetName);
    direction = lower(direction);

    if (!amount || amount < 1) {
      amount = 10;
    }

    if (targetName === "input") {
      nudgeInputBar(direction, amount);
      return;
    }

    if (targetName === "output") {
      nudgeOutputHeight(direction, amount);
      return;
    }

    if (direction === "up") {
      dy = -amount;
    } else if (direction === "down") {
      dy = amount;
    } else if (direction === "left") {
      dx = -amount;
    } else if (direction === "right") {
      dx = amount;
    } else {
      append("Usage: gwl move sidebar/top/bottom/quest/hunt/vitals up/down/left/right [pixels]", warnColor);
      return;
    }

    if (targetName === "sidebar" || targetName === "right") {
      el = byId("sidebar");
    } else if (targetName === "top") {
      el = byId("topsidebar");
    } else if (targetName === "bottom" || targetName === "comms") {
      el = byId("bottomsidebar");
    } else if (targetName === "quest") {
      el = byId("genesisQuestTracker");
    } else if (targetName === "hunt" || targetName === "autohunt") {
      el = byId("gwhuntHud");
    } else if (targetName === "vitals") {
      el = byId("gVitalsHud");
    } else {
      append("Unknown move target. Use: output, input, sidebar, top, bottom, quest, hunt, vitals", warnColor);
      return;
    }

    nudgeElement(el, dx, dy);
    append("Moved " + targetName + " " + direction + " by " + amount + "px.", goodColor);
  }


