  function cleanDockedWindows() {
    var bottom = byId("bottomsidebar");
    var autohuntTab = byId("gwautohunttab");
    var h = byId("gwhuntHud");
    var q = byId("genesisQuestTracker");
    var v = byId("gVitalsHud");
    var staleIds = ["#gwvitalstab", "#gwloottab"];
    var labels = ["vitals", "loot"];
    var links;
    var i;
    var j;
    var el;

    /*
      Remove old Vitals/Loot tabs from earlier versions.
    */
    for (i = 0; i < staleIds.length; i++) {
      el = getEl(staleIds[i]);
      if (el) {
        el.remove();
      }
    }

    links = getAll("ul.idTabs a");

    for (j = links.length - 1; j >= 0; j--) {
      for (i = 0; i < labels.length; i++) {
        if (lower(links[j].textContent) === labels[i]) {
          if (links[j].parentElement) {
            links[j].parentElement.remove();
          }
        }
      }
    }

    /*
      If AutoHunter is inside the autohunt tab, remove nested resizable behavior.
      The tab/panel is already the resizable container; the inner HUD should fill it.
    */
    if (h && autohuntTab && autohuntTab.contains(h)) {
      h.style.position = "relative";
      h.style.left = "0px";
      h.style.top = "0px";
      h.style.width = "calc(100% - 8px)";
      h.style.height = "auto";
      h.style.minHeight = "";
      h.style.maxHeight = "none";
      h.style.resize = "none";
      h.style.overflow = "visible";
      h.style.margin = "0px";
      h.style.boxSizing = "border-box";
    }

    var questTab = byId("gwquesttab");

    if (q && questTab && questTab.contains(q)) {
      q.style.position = "relative";
      q.style.left = "0px";
      q.style.top = "0px";
      q.style.width = "calc(100% - 8px)";
      q.style.height = "360px";
      q.style.minHeight = "";
      q.style.maxHeight = "none";
      q.style.resize = "none";
      q.style.overflow = "auto";
      q.style.margin = "0px";
      q.style.boxSizing = "border-box";
    }

    /*
      Vitals should not live in a tab anymore. Move it back to body so gvitals controls it.
    */
    if (v && bottom && bottom.contains(v)) {
      document.body.appendChild(v);
      v.style.resize = "none";
      v.style.overflow = "hidden";
    }
  }

