  function applyInput() {
    var d = ensureData();
    var cfg = d.input;
    var inputbar = byId("inputbar");
    var input = byId("input");
    var h;
    var bottom;

    if (!inputbar || !input) {
      return;
    }

    h = parseInt(cfg.height, 10);

    if (h) {
      inputbar.style.boxSizing = "border-box";
      inputbar.style.height = h + "px";
      inputbar.style.minHeight = h + "px";
      inputbar.style.zIndex = "999996";

      input.style.boxSizing = "border-box";
      input.style.height = h + "px";
      input.style.minHeight = h + "px";
      input.style.lineHeight = Math.max(18, h - 8) + "px";
      input.style.padding = cfg.mode === "compact" ? "2px 7px" : "3px 8px";
      input.style.resize = "none";
    }

    if (cfg.fontSize) {
      input.style.fontSize = cfg.fontSize;
      input.style.fontFamily = "monospace";
    }

    if (cfg.mode === "wide") {
      inputbar.style.left = "0px";
      inputbar.style.right = "0px";
      inputbar.style.width = "100%";
    } else {
      inputbar.style.left = "";
      inputbar.style.right = "";
      inputbar.style.width = "";
    }

    bottom = parseInt(cfg.bottom, 10);

    /*
      v10: move the input visually with transform instead of trying to convert
      #inputbar into a fixed-position element. The Genesis client keeps #inputbar
      inside its own layout, so fixed positioning can be ignored or behave oddly.
      Positive bottom offset raises the input bar.
    */
    inputbar.style.position = "";
    inputbar.style.left = "";
    inputbar.style.right = "";
    inputbar.style.width = "";
    inputbar.style.bottom = "";

    var leftOffset = parseInt(cfg.left, 10);

    if (isNaN(leftOffset) || cfg.left === "") {
      leftOffset = 0;
    }

    if (!isNaN(bottom) && cfg.bottom !== "") {
      inputbar.style.transform = "translate(" + leftOffset + "px, -" + bottom + "px)";
      inputbar.style.marginBottom = bottom + "px";
      inputbar.style.zIndex = "999996";
    } else if (leftOffset !== 0) {
      inputbar.style.transform = "translateX(" + leftOffset + "px)";
      inputbar.style.marginBottom = "";
      inputbar.style.zIndex = "999996";
    } else {
      inputbar.style.transform = "";
      inputbar.style.marginBottom = "";
    }

    if (cfg.width) {
      inputbar.style.width = cfg.width + "px";
      input.style.width = "100%";
    } else if (cfg.mode !== "wide") {
      inputbar.style.width = "";
      input.style.width = "";
    }

    var gap = parseInt(cfg.gap, 10);

    if (!isNaN(gap) && cfg.gap !== "") {
      inputbar.style.marginTop = gap + "px";
    } else {
      inputbar.style.marginTop = "";
    }

    if (cfg.style === "neon") {
      inputbar.style.background = "rgba(0,0,0,0.92)";
      inputbar.style.borderTop = "1px solid #0f4040";
      inputbar.style.borderBottom = "1px solid #0f4040";

      input.style.background = "#020607";
      input.style.color = "#80ff80";
      input.style.border = "1px solid #1bbf80";
      input.style.outline = "none";
      input.style.boxShadow = "0 0 8px rgba(27,191,128,0.35)";
    } else {
      inputbar.style.background = "";
      inputbar.style.borderTop = "";
      inputbar.style.borderBottom = "";

      input.style.background = "";
      input.style.color = "";
      input.style.border = "";
      input.style.outline = "";
      input.style.boxShadow = "";
    }
  }

