      return;
    }

    if (sub === "reset") {
      resetInput();
      return;
    }

    if (sub === "height") {
      setInputHeight(a3);
      return;
    }

    if (sub === "font") {
      setInputFont(a3);
      return;
    }

    if (sub === "bottom") {
      setInputBottom(a3);
      return;
    }

    if (sub === "left") {
      setInputLeft(a3);
      return;
    }

    if (sub === "width") {
      setInputWidth(a3);
      return;
    }

    if (sub === "gap" || sub === "spacing") {
      setInputGap(a3);
      return;
    }

    if (sub === "compact") {
      setInputMode("compact");
      return;
    }

    if (sub === "normal") {
      setInputMode("normal");
      return;
    }

    if (sub === "wide") {
      setInputMode("wide");
      return;
    }

    if (sub === "style") {
      setInputStyle(a3);
      return;
    }

    append("Unknown input command. Use: gwl input help", warnColor);
  }

