  function dispatch() {
    var action = lower(args[1]);
    var a2 = args[2];
    var a3 = args[3];

    ensureData();

    if (!action || action === "help") {
      help();
      return;
    }

    if (action === "apply") {
      applyLayout();
      return;
    }

    if (action === "reset") {
      resetLayout();
      return;
    }

    if (action === "status") {
      status();
      return;
    }

    if (action === "drag") {
      if (lower(a2) === "reset") {
        resetDragMode();
        return;
      }

      enableDragMode();
      return;
    }

    if (action === "handle") {
      setDragHandlePosition(a2);
      return;
    }

    if (action === "move" || action === "nudge") {
      nudgeNamedTarget(a2, a3, args[4]);
      return;
    }

    if (action === "lock") {
      disableDragMode();
      return;
    }

    if (action === "align") {
      alignMainWidths();
      return;
    }

    if (action === "stack" || action === "spacing") {
      applyCleanStackPreset();
      return;
    }

    if (action === "clean") {
      cleanDockedWindows();
      append("Cleaned docked windows/tabs.", goodColor);
      return;
    }

    if (action === "fixinput") {
      hardResetInputVisuals();
      append("Input bar restored.", goodColor);
      return;
    }

    if (action === "dock") {
      setupTabs();
      forceDockQuestAndHunt();
      startDockKeeper();
      append("Quest Tracker and AutoHunter forced back into bottom tabs.", goodColor);
      return;
    }

    if (action === "tabs") {
      a2 = lower(a2);

      if (a2 === "setup" || a2 === "on") {
        setupTabs();
        return;
      }

      if (a2 === "refresh") {
        refreshTabs();
        return;
      }

      if (a2 === "float") {
        floatCustomWindows();
        return;
      }

      if (a2 === "reset" || a2 === "off" || a2 === "remove") {
        resetTabs();
        return;
      }

      append("Usage: gwl tabs setup/refresh/float/reset", warnColor);
      return;
    }

    if (action === "vitals") {
      setVitals(a2);
      return;
    }

    if (action === "sidebar") {
      setSidebar(a2, a3);
      return;
    }

    if (action === "top") {
      setTop(a2);
      return;
    }

    if (action === "comms" || action === "communication") {
      setComms(a2, a3);
      return;
    }

    if (action === "map" || action === "magicmap") {
      setMap(a2);
      return;
    }

    if (action === "connected" || action === "connection") {
      setConnected(a2);
      return;
    }

    if (action === "controls") {
      setControls(a2);
      return;
    }

    if (action === "controls") {
      if (lower(a2) === "reset" || lower(a2) === "normal" || lower(a2) === "show") {
        resetControlsVisuals();
        save();
        append("Controls restored.", goodColor);
        return;
      }

      append("Usage: gwl controls reset", warnColor);
      return;
    }

    if (action === "input") {
      handleInputCommand(a2, a3);
      return;
    }

    if (action === "output") {
      handleOutputCommand(a2, a3);
      return;
    }

    append("Unknown command. Use: gwl help", warnColor);
  }

  window.GenesisWebLayout = window.GenesisWebLayout || {};
  window.GenesisWebLayout.apply = applyLayout;
  window.GenesisWebLayout.reset = resetLayout;
  window.GenesisWebLayout.tabs = setupTabs;
  window.GenesisWebLayout.refreshTabs = refreshTabs;

  dispatch();
})();

/*
Kill All / Count Attack v69
Alias value: ka

Usage:
  target bunny
  kaskill cdonk
  ka

or:
  ka bunny

This follows the Exosphere count-based style, with optional guild skill opener.
*/

gwc.userdata.kaTarget = args["*"] || args[1] || gwc.userdata.kaTarget || gwc.userdata.enemy;

let target = gwc.userdata.kaTarget;

if (!target) {
  gwc.output.append("[KA] Usage: ka <target>  OR  target <target> then ka", "#ffcc66");
} else {
  target = String(target).trim().toLowerCase();

  let countTarget = target;

  if (countTarget.endsWith("f")) {
    countTarget = countTarget.replace(/f$/g, "ve"); // elf -> elves, dwarf -> dwarves
  }

  if (countTarget.endsWith("y")) {
    countTarget = countTarget.replace(/y$/g, "ie"); // bunny -> bunnies
  }

  if (countTarget.endsWith("s")) {
    countTarget = countTarget.replace(/s$/g, "se"); // phrynos -> phrynoses
  }

  gwc.userdata.kaTarget = target;
  gwc.userdata.enemy = target; // backward compatibility

  try {
    gwc.trigger.enable("Target Counter");
  } catch (e) {
    gwc.output.append("[KA] Could not enable Target Counter trigger: " + e.message, "#ff6666");
  }

  gwc.output.append("[KA] Counting " + target + "...", "#ffb347");

  if (target === "drow") {
    gwc.connection.send("count all drow");
  } else {
    gwc.connection.send("count " + countTarget + "s");
  }
}

